WITH b AS (SELECT s.closing_balance AS p, s.interest_rate_pct/1200 AS r0, (s.interest_rate_pct+3)/1200 AS r1, l.term_months-s.months_on_book AS n FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) WHERE s.snapshot_date=DATE '2025-12-31' AND s.loan_status<>'Closed' AND s.repayment_type='P&I' AND l.term_months-s.months_on_book>=12 AND s.interest_rate_pct>0) SELECT ROUND(SUM(p*r0/(1-POWER(1+r0,-n))),0), ROUND(SUM(p*r1/(1-POWER(1+r1,-n))),0), ROUND(100*(SUM(p*r1/(1-POWER(1+r1,-n)))/SUM(p*r0/(1-POWER(1+r0,-n)))-1),1) FROM b
